// Unreachable reports whether an error is the driver failing to reach
// PostgreSQL — a name that did not resolve, a refused connection, a dial that
// timed out — rather than PostgreSQL rejecting something. Such an error carries
// no SQLSTATE, so the SQLSTATE tables in internal/server and internal/mcp
// cannot classify it, and its Error() carries fragments of the DSN: the
// database role, the database name and the internal host:port. It must never
// reach a client verbatim; the callers answer with a generic server error and
// keep the original in the log.
func Unreachable(err error) bool {
	var connErr *pgconn.ConnectError
	return errors.As(err, &connErr)
}

// Interrupted reports whether a query was cut short rather than answered — the
// caller went away and net/http cancelled the request context, or a deadline
// passed. pgx returns ctx.Err() from the connection-acquisition step, so such an
// error carries no SQLSTATE and is no *pgconn.ConnectError either; it used to
// fall past every classification and be answered as a malformed request.
// Interrupting a query is a server-side event, so the callers answer with a
// generic server error and keep the original in the log.
//
// Why a context predicate lives in the database package: the same reason as
// Unreachable above — internal/server and internal/mcp both read this one
// definition, so a database error gets the same verdict whichever door the
// caller came through.
func Interrupted(err error) bool {
	return errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded)
}

func Open(ctx context.Context, dsn string, logger *slog.Logger) (*pgxpool.Pool, error) {
	var lastErr error
	for attempt := 1; attempt <= 20; attempt++ {
		pool, err := pgxpool.New(ctx, dsn)
		if err == nil {
			err = pool.Ping(ctx)
		}
		if err == nil {
			return pool, nil
		}
		if pool != nil {
			pool.Close()
		}
		lastErr = err
		logger.Warn("waiting for PostgreSQL", "attempt", attempt, "error", err)
		select {
		case <-ctx.Done():
			return nil, ctx.Err()
		case <-time.After(1500 * time.Millisecond):
		}
	}
	return nil, fmt.Errorf("connect PostgreSQL: %w", lastErr)
}

func Migrate(ctx context.Context, pool *pgxpool.Pool) error {
	conn, err := pool.Acquire(ctx)
	if err != nil {
		return err
	}
	defer conn.Release()
	if _, err = conn.Exec(ctx, "SELECT pg_advisory_lock($1)", migrationLockID); err != nil {
		return fmt.Errorf("migration lock: %w", err)
	}
	defer func() { _, _ = conn.Exec(context.Background(), "SELECT pg_advisory_unlock($1)", migrationLockID) }()
	if _, err = conn.Exec(ctx, `CREATE TABLE IF NOT EXISTS schema_migrations (version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now())`); err != nil {
		return err
	}
	entries, err := fs.ReadDir(migrations.Files, ".")
	if err != nil {
		return err
	}
	sort.Slice(entries, func(i, j int) bool { return entries[i].Name() < entries[j].Name() })
	for _, entry := range entries {
		if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".sql") {
			continue
