	ResolvedAt   *time.Time   `json:"resolvedAt,omitempty"`
	AcceptedNote string       `json:"acceptedNote,omitempty"`
	Status       string       `json:"status"`
}

// RiskFactor is one contribution to a score. Points are the arithmetic; detail
